public class Main {
    public static void main(String[] args) {
        String userId    = "USR-001";
        String productId = "PRD-42";
        double amount    = 149.99;

        // Client must create and manage all subsystems
        InventoryService inventory = new InventoryService();
        PaymentService   payment   = new PaymentService();
        InvoiceService   invoice   = new InvoiceService();
        EmailService     email     = new EmailService();

        System.out.println("--- Placing Order ---");

        // Step 1: Check stock
        if (!inventory.checkStock(productId)) {
            System.out.println("Order failed: Product out of stock.");
            return;
        }

        // Step 2: Process payment
        if (!payment.processPayment(userId, amount)) {
            System.out.println("Order failed: Payment declined.");
            return;
        }

        // Step 3: Reserve the item
        inventory.reserveItem(productId);

        // Step 4: Generate invoice
        String invoiceId = invoice.generateInvoice(userId, productId, amount);

        // Step 5: Send confirmation
        email.sendConfirmation(userId, invoiceId);

        System.out.println("Order placed successfully!");
    }
}

